import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr02803Controller {
  @Post('/notifications/read-all')
  @HttpCode(200)
  async readAllNotifications(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    return transaction(async (db) => {
      const changed = await db.execute(
        `UPDATE notification
            SET read_yn = true,
                read_at = now(),
                updated_at = now()
          WHERE employee_id = CAST(:userId AS bigint)
            AND read_yn = false`,
        { userId: user.id },
      );
      if (changed === 0) {
        throw new ApiError(409, 'NO_UNREAD_NOTIFICATIONS', '읽지 않은 알림이 없습니다.');
      }
      return { updatedCount: Number(changed) };
    });
  }

  @Post('/notifications/:notificationId/read')
  @HttpCode(200)
  async readNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = req.params['notificationId'];
    if (!/^[0-9]{1,18}$/.test(notificationId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `UPDATE notification
            SET read_yn = true,
                read_at = COALESCE(read_at, now()),
                updated_at = now()
          WHERE notification_id = CAST(:notificationId AS bigint)
            AND employee_id = CAST(:userId AS bigint)
        RETURNING notification_id AS "notificationId",
                  read_yn AS "readYn",
                  read_at AS "readAt"`,
        { notificationId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '해당 알림을 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

