import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, LookupSelect, Num, RefName, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02803Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [drawer, setDrawer] = useState<'' | 'all' | 'one'>('');
  const [notificationId, setNotificationId] = useState<number | string>('');

  const addResult = (row: Row) => {
    setResults((prev) => [row, ...prev]);
  };

  const readAll = async () => {
    const res = await call<Row>('POST', '/notifications/read-all', role, {});
    addResult({
      key: 'all-' + Date.now(),
      kind: '모두 읽음',
      notificationId: '',
      updatedCount: res.updatedCount,
      readAt: new Date().toISOString(),
    });
    notify('모든 알림을 읽음 처리했습니다.');
    setDrawer('');
  };

  const readOne = async () => {
    if (notificationId === '' || notificationId === undefined) {
      throw new Error('알림을 선택하세요.');
    }
    const res = await call<Row>('POST', '/notifications/' + notificationId + '/read', role, {});
    addResult({
      key: 'one-' + Date.now(),
      kind: '개별 읽음',
      notificationId: res.notificationId,
      updatedCount: 1,
      readAt: res.readAt,
    });
    notify('알림을 읽음 처리했습니다.');
    setNotificationId('');
    setDrawer('');
  };

  const total = results.reduce((sum, r) => sum + Number(r.updatedCount || 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 횟수', <Num value={results.length} />],
            ['읽음으로 변경된 알림', <Num value={total} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>읽음 처리 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setDrawer('one')}>개별 읽음 처리</button>
          <button type="button" onClick={() => setDrawer('all')}>모두 읽음 처리</button>
        </Band>
        <DataTable
          columns={[
            { key: 'kind', label: '처리 구분' },
            {
              key: 'notificationId',
              label: '알림 ID',
              render: (r: Row) => (r.notificationId ? <RefName table="notification" role={role} value={r.notificationId} /> : <span>전체</span>),
            },
            { key: 'readYn', label: '읽음 여부', render: () => <Badge value="읽음" /> },
            { key: 'updatedCount', label: '읽음으로 변경된 알림 수', render: (r: Row) => <Num value={r.updatedCount} /> },
            { key: 'readAt', label: '읽음 일시', render: (r: Row) => <DateText value={r.readAt} time /> },
          ]}
          rows={results}
          empty="이 화면에서 처리한 읽음 내역이 없습니다."
        />
      </section>
      {drawer === 'all' && (
        <Drawer title="모두 읽음 처리" onClose={() => setDrawer('')}>
          <Form onSubmit={readAll} submit="모두 읽음 처리" note="본인의 읽지 않은 알림과 @멘션을 모두 읽음 상태로 변경합니다." />
        </Drawer>
      )}
      {drawer === 'one' && (
        <Drawer title="개별 읽음 처리" onClose={() => setDrawer('')}>
          <Form onSubmit={readOne} submit="읽음 처리">
            <Field label="알림 ID" required wide>
              <LookupSelect table="notification" role={role} value={notificationId} onChange={setNotificationId} placeholder="알림 선택" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
